WITH parsed AS (SELECT id, log_ts, level, status_code, context, COALESCE(context['region'], 'none') AS region_or_default, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs) SELECT id, status_code, region_or_default, tier, MAX(status_code) OVER w_running AS running_max_status_code, AVG(status_code) OVER w_running AS running_avg_status_code, MIN(status_code) OVER w_running AS running_min_status_code, SUM(status_code) OVER w_running AS running_sum_status_code, AVG(status_code) OVER (PARTITION BY tier ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS status_code_avg_1h FROM parsed WINDOW w_running AS (PARTITION BY tier ORDER BY status_code, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
